select ref_0.favorite_color as c0, ref_0.balance as c1, (select log_time from public.measurements limit 1 offset 6) as c2, ref_0.id as c3 from public.users as ref_0 where cast(null as bpchar) <= case when pg_catalog.gen_random_uuid() = case when ref_0.metadata @? case when ref_0.age is NULL then cast(null as jsonpath) else cast(null as jsonpath) end then cast(null as uuid) else cast(null as uuid) end then cast(null as bpchar) else cast(null as bpchar) end limit 27;
